def _nll_kernel(log_prob_ref, y_true_ref, mask_ref, out_ref, acc_ref):
    time_block = pl.program_id(1)

    @pl.when(time_block == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    labels = y_true_ref[...].astype(jnp.int32)
    selected = jnp.take_along_axis(
        log_prob_ref[...], labels[..., None], axis=2
    )[..., 0].astype(jnp.float32)
    weights = mask_ref[...].astype(jnp.float32)

    numerator = acc_ref[:, 0] + jnp.sum(selected * weights, axis=1)
    denominator = acc_ref[:, 1] + jnp.sum(weights, axis=1)
    acc_ref.at[:, 0].set(numerator)
    acc_ref.at[:, 1].set(denominator)

    @pl.when(time_block == pl.num_programs(1) - 1)
    def _finish():
        out_ref.at[:, 0].set(-numerator / denominator)


def workload(log_prob, y_true, mask):
    batch, time, num_classes = log_prob.shape
    batch_block = 16
    time_block = 128
    out_width = 128

    result = pl.pallas_call(
        _nll_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(batch // batch_block, time // time_block),
            in_specs=[
                pl.BlockSpec(
                    (batch_block, time_block, num_classes),
                    lambda b, t: (b, t, 0),
                ),
                pl.BlockSpec(
                    (batch_block, time_block), lambda b, t: (b, t)
                ),
                pl.BlockSpec(
                    (batch_block, time_block), lambda b, t: (b, t)
                ),
            ],
            out_specs=pl.BlockSpec(
                (batch_block, out_width), lambda b, t: (b, 0)
            ),
            scratch_shapes=[
                pltpu.VMEM((batch_block, out_width), jnp.float32)
            ],
        ),
        out_shape=jax.ShapeDtypeStruct((batch, out_width), jnp.float32),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "arbitrary")
        ),
    )(log_prob, y_true, mask)

    return result[:, 0].astype(log_prob.dtype)

