def _tiles(m, k, n):
    bm = next((b for b in (1024, 512, 256, 128, 64, 32, 16, 8) if m % b == 0), m)
    bk = next((b for b in (256, 128) if k % b == 0), k)
    bn = next((b for b in (1024, 512, 256, 128) if n % b == 0), n)
    return bm, bk, bn


def _first_kernel(x_ref, w_ref, b_ref, out_ref, acc_ref):
    step = pl.program_id(2)

    @pl.when(step == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    lhs = x_ref[...].astype(jnp.bfloat16)
    acc_ref[...] += jax.lax.dot_general(
        lhs,
        w_ref[...],
        (((1,), (0,)), ((), ())),
        preferred_element_type=jnp.float32,
    )

    @pl.when(step == pl.num_programs(2) - 1)
    def _finish():
        value = jnp.maximum(acc_ref[...] + b_ref[...], 0.0)
        out_ref[...] = value.astype(out_ref.dtype)


def _second_kernel(h_ref, w_ref, b_ref, out_ref):
    step = pl.program_id(2)

    @pl.when(step == 0)
    def _init():
        out_ref[...] = jnp.zeros_like(out_ref)

    out_ref[...] += jax.lax.dot_general(
        h_ref[...],
        w_ref[...],
        (((1,), (0,)), ((), ())),
        preferred_element_type=jnp.float32,
    )

    @pl.when(step == pl.num_programs(2) - 1)
    def _finish():
        out_ref[...] = jnp.tanh(out_ref[...] + b_ref[...])


def _first(x, w, b, m, k, n):
    bm, bk, bn = _tiles(m, k, n)
    grid = (m // bm, n // bn, k // bk)
    return pl.pallas_call(
        _first_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=[
                pl.BlockSpec((bm, bk), lambda i, j, r: (i, r)),
                pl.BlockSpec((bk, bn), lambda i, j, r: (r, j)),
                pl.BlockSpec((1, bn), lambda i, j, r: (0, j)),
            ],
            out_specs=pl.BlockSpec((bm, bn), lambda i, j, r: (i, j)),
            scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, n), jnp.bfloat16),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=('parallel', 'parallel', 'arbitrary')
        ),
    )(x, w, b)


def _second(h, w, b, m, k, n, out_dtype):
    bm, bk, bn = _tiles(m, k, n)
    grid = (m // bm, n // bn, k // bk)
    return pl.pallas_call(
        _second_kernel,
        grid=grid,
        in_specs=[
            pl.BlockSpec((bm, bk), lambda i, j, r: (i, r)),
            pl.BlockSpec((bk, bn), lambda i, j, r: (r, j)),
            pl.BlockSpec((1, bn), lambda i, j, r: (0, j)),
        ],
        out_specs=pl.BlockSpec((bm, bn), lambda i, j, r: (i, j)),
        out_shape=jax.ShapeDtypeStruct((m, n), out_dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=('parallel', 'parallel', 'arbitrary')
        ),
    )(h, w, b)


@jax.jit
def workload(x, w1, b1, w2, b2):
    leading_shape = x.shape[:-1]
    k = x.shape[-1]
    hidden = w1.shape[1]
    output = w2.shape[1]
    m = x.size // k

    x2d = x.reshape((m, k))
    w1_bf16 = w1.astype(jnp.bfloat16)
    w2_bf16 = w2.astype(jnp.bfloat16)

    h = _first(x2d, w1_bf16, b1.reshape((1, hidden)), m, k, hidden)
    y = _second(h, w2_bf16, b2.reshape((1, output)), m, hidden, output, x.dtype)
    return y.reshape(leading_shape + (output,))

