def _row_sums_kernel(x_ref, pos_ref, out_ref):
    col = pl.program_id(1)

    @pl.when(col == 0)
    def _init():
        out_ref[...] = jnp.zeros_like(out_ref)

    x = x_ref[...].astype(jnp.float32)
    pos = pos_ref[...].astype(jnp.float32)
    hinge = jnp.maximum(x - pos + 4.0, 0.0)
    out_ref[...] += jnp.sum(hinge, axis=1, dtype=jnp.float32)

    @pl.when(col == pl.num_programs(1) - 1)
    def _remove_positive_column():
        out_ref[...] -= 4.0


def _finalize_kernel(sums_ref, out_ref, *, normalizer):
    total = jnp.sum(sums_ref[...], dtype=jnp.float32)
    value = (total / normalizer).astype(out_ref.dtype)
    out_ref[...] = jnp.reshape(value, (1,))


