def _focal_bce_kernel(x_ref, target_ref, out_ref, acc_ref):
    block_id = pl.program_id(0)

    @pl.when(block_id == 0)
    def _init_acc():
        acc_ref[...] = jnp.zeros((1,), dtype=jnp.float32)

    x = x_ref[...].astype(jnp.float32)
    target = target_ref[...].astype(jnp.float32)

    pt = jax.nn.sigmoid(x)
    one_minus_pt = 1.0 - pt
    loss = (
        -0.25 * one_minus_pt * one_minus_pt * target * jnp.log(pt)
        - 0.75 * pt * pt * (1.0 - target) * jnp.log(one_minus_pt)
    )
    acc_ref[...] += jnp.sum(loss, dtype=jnp.float32)

    @pl.when(block_id == pl.num_programs(0) - 1)
    def _store_result():
        out_ref[...] = acc_ref[...] * (1.0 / 54.0)


